using FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.ValueObjects;

namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Aggregates;

/// <summary>
/// A reading captured by a cattle band and relayed by an Edge Gateway. Its identity is the device identifier
/// together with the reading identifier generated by the firmware, which never changes across retries.
/// </summary>
public sealed class TelemetryReading
{
    // US-13: a reading older than 24 hours is reported with its age and is never presented as current.
    public static readonly TimeSpan StalenessLimit = TimeSpan.FromHours(24);

    public Guid Id { get; private set; }
    public Guid ReadingId { get; private set; }
    public Guid DeviceId { get; private set; }
    public Guid GatewayId { get; private set; }
    public Guid RanchId { get; private set; }
    public Guid? CattleId { get; private set; }
    public DateTimeOffset RecordedAt { get; private set; }
    public DateTimeOffset ReceivedAt { get; private set; }
    public Measurement BodyTemperature { get; private set; } = Measurement.Absent();
    public Measurement ActivityIndex { get; private set; } = Measurement.Absent();
    public Measurement RuminationMinutes { get; private set; } = Measurement.Absent();
    public Measurement BatteryPercent { get; private set; } = Measurement.Absent();
    public PositionMeasurement Position { get; private set; } = PositionMeasurement.Absent();

    private TelemetryReading()
    {
    }

    public TelemetryReading(
        Guid readingId,
        Guid deviceId,
        DateTimeOffset recordedAt,
        Measurement bodyTemperature,
        Measurement activityIndex,
        Measurement ruminationMinutes,
        Measurement batteryPercent,
        PositionMeasurement position,
        Guid gatewayId,
        Guid ranchId,
        Guid? cattleId,
        DateTimeOffset receivedAt)
    {
        if (readingId == Guid.Empty || deviceId == Guid.Empty || gatewayId == Guid.Empty || ranchId == Guid.Empty)
        {
            throw MonitoringException.InvalidInput("Reading, device, gateway and ranch identifiers are required.");
        }

        if (cattleId == Guid.Empty)
        {
            throw MonitoringException.InvalidInput("An attributed cattle identifier cannot be empty.");
        }

        EnsureNonNegative(activityIndex, "Activity index");
        EnsureNonNegative(ruminationMinutes, "Rumination minutes");
        if (batteryPercent.Value is < 0 or > 100)
        {
            throw MonitoringException.InvalidInput("Battery level must be between 0 and 100 percent.");
        }

        Id = Guid.NewGuid();
        ReadingId = readingId;
        DeviceId = deviceId;
        RecordedAt = recordedAt.ToUniversalTime();
        BodyTemperature = bodyTemperature;
        ActivityIndex = activityIndex;
        RuminationMinutes = ruminationMinutes;
        BatteryPercent = batteryPercent;
        Position = position;
        GatewayId = gatewayId;
        RanchId = ranchId;
        CattleId = cattleId;
        ReceivedAt = receivedAt.ToUniversalTime();
    }

    public bool IsStale(DateTimeOffset now) => now - RecordedAt > StalenessLimit;

    public Measurement MeasurementOf(MonitoredMetric metric) => metric switch
    {
        MonitoredMetric.BodyTemperature => BodyTemperature,
        MonitoredMetric.ActivityIndex => ActivityIndex,
        _ => throw new ArgumentOutOfRangeException(nameof(metric), metric, null)
    };

    // Relaying gateway and reception time are not part of the captured content.
    public bool HasSameCaptureAs(TelemetryReading other) =>
        ReadingId == other.ReadingId &&
        DeviceId == other.DeviceId &&
        RecordedAt == other.RecordedAt &&
        BodyTemperature == other.BodyTemperature &&
        ActivityIndex == other.ActivityIndex &&
        RuminationMinutes == other.RuminationMinutes &&
        BatteryPercent == other.BatteryPercent &&
        Position == other.Position;

    private static void EnsureNonNegative(Measurement measurement, string name)
    {
        if (measurement.Value < 0)
        {
            throw MonitoringException.InvalidInput($"{name} cannot be negative.");
        }
    }
}
